<script>
(()=>{'use strict';const stack=document.getElementById('panel-stack'),toast=document.getElementById('toast');const row=(a,b,c='')=>`<div class="row"><div class="row-main"><strong>${a}</strong><small>${b}</small></div>${c}</div>`;const toggle=(a,b,key,on=true)=>row(a,b,`<button class="toggle ${on?'on':''}" data-layer="${key}" aria-label="Afficher ${a}"></button>`);const panels={mission:{k:'OPERATIONS',t:'MISSION',b:`<div class="card"><div class="card-title">EXERCISE FALCON <span class="badge">ACTIVE</span></div><div class="card-body"><div class="data"><span>UNITS</span><b>4</b></div><div class="data"><span>OBJECTIVES</span><b>3</b></div><div class="data"><span>PENDING TASKS</span><b>2</b></div></div></div><div class="eyebrow">TASKS & ORDERS</div>${row('TASK-004','ALPHA · SECURE AO FALCON','<span class="badge amber">ACK 2/3</span>')}${row('TASK-005','BRAVO · ESTABLISH SCREEN','<span class="badge">PENDING</span>')}<div class="eyebrow">MISSION EVENTS</div>${row('13:51 · CONTACT C-018','3 SOURCES · CONFIDENCE 82%','<span class="badge red">INTEL</span>')}${row('13:48 · UAV IMAGERY','AO FALCON','<span class="badge">ISR</span>')}`},layers:{k:'CARTOGRAPHY',t:'LAYERS',b:`<input class="search" placeholder="Filtrer les couches…"><div class="eyebrow">BFT</div>${toggle('Friendly units','12 VISIBLE','units')}${toggle('Vehicles','4 VISIBLE','vehicles')}${toggle('Tactical labels','ACTIVE','labels')}<div class="eyebrow">MISSION</div>${toggle('Objectives','3 AREAS','objectives')}${toggle('Routes','2 ACTIVE','routes')}${toggle('AOI / control measures','4 ZONES','zones')}<div class="eyebrow">INTELLIGENCE</div>${toggle('SSE / BII','6 RECORDS','intel')}${toggle('Activity heatmap','REAL EVENTS','heat')}<div class="eyebrow">SENSORS</div>${toggle('UAV / ISR','1 AIRBORNE','uav')}${toggle('Helmet cameras','3 FEEDS','helmet',false)}`},imagery:{k:'INTELLIGENCE',t:'IMAGERY',b:`<input class="search" placeholder="Rechercher une image…"><div class="eyebrow">GEOREFERENCED MEDIA</div><div class="card"><div class="card-title">UAV-01 / AO FALCON <span class="badge">ISR</span></div><div class="imagery"></div></div><div class="card"><div class="card-title">ALPHA 1-2 / PHOTO <span class="badge">FIELD</span></div><div class="imagery"></div></div>`},intel:{k:'SENSOR FUSION',t:'INTELLIGENCE',b:`<div class="card"><div class="card-title">CONTACT C-018 <span class="badge red">82%</span></div><div class="card-body"><div class="data"><span>UAV-01</span><b>13:41</b></div><div class="data"><span>ALPHA 1-2</span><b>13:43</b></div><div class="data"><span>SSE REPORT</span><b>13:47</b></div><div class="data"><span>HELMET CAM</span><b>13:48</b></div></div></div><div class="eyebrow">WATCHLIST</div>${row('AO FALCON','AREA OF INTEREST','<span class="badge">4 ALERTS</span>')}${row('C-018','TRACKED CONTACT','<span class="badge red">3 SOURCES</span>')}`},comms:{k:'TRANSMISSIONS',t:'COMMS',b:`<input class="search" placeholder="Canal ou indicatif…"><div class="eyebrow">CHANNELS</div>${row('FALCON HQ','COMMAND NET · 6 ONLINE','<span class="badge">LIVE</span>')}${row('ALPHA','GROUP CHANNEL · 8 ONLINE')}${row('BRAVO','GROUP CHANNEL · 4 ONLINE')}<div class="eyebrow">RECENT</div>${row('13:52 · ALPHA','AO SECURED, CONTINUING SEARCH')}${row('13:50 · HQ','COPY. MAINTAIN OBSERVATION.')}`},tools:{k:'SYSTEM',t:'TOOLS',b:`<div class="eyebrow">MAP TOOLS</div>${row('Coordinate tool','GRID / MGRS / LATLON','<span class="badge">OPEN</span>')}${row('Route planner','TACTICAL ROUTES','<span class="badge">OPEN</span>')}${row('Measure','DISTANCE / BEARING','<span class="badge">OPEN</span>')}${row('Mission replay','TIMELINE / AAR','<span class="badge">OPEN</span>')}`}};
function openPanel(name,stackPanel=false){const p=panels[name];if(!p)return;if(!stackPanel)stack.innerHTML='';const el=document.createElement('section');el.className='panel';el.dataset.name=name;el.innerHTML=`<div class="panel-head"><div><small>${p.k}</small><strong>${p.t}</strong></div><button class="close" aria-label="Fermer">×</button></div><div class="panel-body">${p.b}</div>`;stack.append(el);el.querySelector('.close').onclick=()=>el.remove();el.querySelectorAll('.toggle').forEach(t=>t.onclick=()=>{t.classList.toggle('on');const visible=t.classList.contains('on'),key=t.dataset.layer;if(key==='routes')document.querySelectorAll('.layer-routes').forEach(x=>x.hidden=!visible);if(key==='heat')document.querySelectorAll('.layer-heat').forEach(x=>x.hidden=!visible);if(key==='units')document.querySelectorAll('.unit').forEach(x=>x.hidden=!visible)})}
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=e=>openPanel(b.dataset.open,e.shiftKey));document.querySelectorAll('.nav button').forEach(b=>b.onclick=e=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));b.classList.add('active');if(b.dataset.panel)openPanel(b.dataset.panel,e.shiftKey);else stack.innerHTML=''});const inspector=document.getElementById('inspector');document.querySelectorAll('.unit').forEach(u=>u.onclick=e=>{e.stopPropagation();document.querySelectorAll('.unit').forEach(x=>x.classList.remove('selected'));u.classList.add('selected');document.getElementById('inspector-title').textContent=u.dataset.unit;inspector.classList.add('show')});document.getElementById('inspector-close').onclick=()=>inspector.classList.remove('show');document.getElementById('replay-button').onclick=()=>document.getElementById('mission-timeline').classList.toggle('show');
const map=document.getElementById('map-stage'),context=document.getElementById('map-context-menu');map.addEventListener('contextmenu',e=>{if(e.target.closest('.panel,.inspector,.palette-backdrop'))return;e.preventDefault();const r=map.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;context.style.left=Math.max(4,Math.min(x,r.width-230))+'px';context.style.top=Math.max(4,Math.min(y,r.height-262))+'px';document.getElementById('context-grid').textContent=`GRID ${String(Math.round(x)).padStart(4,'0')} ${String(Math.round(y)).padStart(4,'0')}`;context.classList.add('show')});document.addEventListener('click',e=>{if(!context.contains(e.target))context.classList.remove('show')});context.querySelector('[data-action="sitrep"]').onclick=()=>{context.classList.remove('show');toast.querySelector('small').textContent='ATHENA / TRANSMISSION';toast.querySelector('strong').textContent='SITREP transmis à FALCON HQ.';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400)};
const palette=document.getElementById('command-palette'),search=document.getElementById('command-search');function openPalette(){palette.classList.add('show');setTimeout(()=>search.focus(),20)}document.getElementById('palette-button').onclick=openPalette;palette.onclick=e=>{if(e.target===palette)palette.classList.remove('show')};document.addEventListener('keydown',event=>{if((event.ctrlKey || event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openPalette()}if(event.key==='Escape'){palette.classList.remove('show');context.classList.remove('show')}});search.oninput=()=>{const q=search.value.toLowerCase();document.querySelectorAll('.command').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(q))};setTimeout(()=>{toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2500)},700)})();
</script>
</body></html>
